var round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
var num = (n) => Number.isFinite(Number(n)) ? Number(n) : 0;
function hourlyCostFromMonthlySalary(salary) {
	return round2(Math.max(0, num(salary)) / 220);
}
function materialCost(l) {
	return round2(num(l.qty) * num(l.unit_cost));
}
function operationHours(l, quantity) {
	return num(l.setup_h) + num(l.time_min) / 60 * num(quantity);
}
function operationHourlyCost(l) {
	const salaryCost = l.cargo_id && l.salary_monthly != null ? hourlyCostFromMonthlySalary(l.salary_monthly) : 0;
	return round2(num(l.cost_hour) + salaryCost);
}
function operationCost(l, quantity) {
	return round2(operationHours(l, quantity) * operationHourlyCost(l));
}
function computeQuote(input) {
	const q = num(input.quantity);
	const materials = round2(input.materials.reduce((s, l) => s + materialCost(l), 0));
	const operations = round2(input.operations.reduce((s, l) => s + operationCost(l, q), 0));
	const services = round2(input.services.reduce((s, l) => s + materialCost(l), 0));
	const subtotal = round2(materials + operations + services);
	const a = input.adjustments ?? {};
	const perda = round2(materials * num(a.perda_material_pct) / 100);
	const margem = round2((subtotal + perda) * num(a.margem_pct) / 100);
	const imposto = round2((subtotal + perda + margem) * num(a.imposto_pct) / 100);
	const total = round2(subtotal + perda + margem + imposto);
	return {
		materials,
		operations,
		services,
		subtotal,
		perda,
		margem,
		imposto,
		total,
		unit: q > 0 ? round2(total / q) : 0
	};
}
function productionEstimate(operations, quantity, hoursPerDay) {
	const setup = operations.reduce((s, l) => s + num(l.setup_h), 0);
	const run = operations.reduce((s, l) => s + num(l.time_min) / 60 * num(quantity), 0);
	const hours = round2(setup + run);
	const days = hoursPerDay > 0 ? Math.round(hours / hoursPerDay * 10) / 10 : 0;
	const manual = operations.filter((o) => o.time_source === "manual").length;
	return {
		setup: round2(setup),
		run: round2(run),
		hours,
		days,
		manual,
		parametro: operations.length - manual
	};
}
function technicalPendencies(specs, ctx) {
	const p = [];
	if (!specs.desenho?.trim()) p.push({
		field: "desenho",
		message: "Desenho técnico não informado",
		severity: "alta"
	});
	if (!specs.tolerancia?.trim()) p.push({
		field: "tolerancia",
		message: "Tolerância não especificada",
		severity: "alta"
	});
	if (specs.tratamento_termico_aplicavel && !specs.tratamento_termico?.trim()) p.push({
		field: "tratamento_termico",
		message: "Tratamento térmico aplicável, mas não especificado",
		severity: "media"
	});
	if (ctx.materials === 0) p.push({
		field: "materiais",
		message: "Nenhum material lançado",
		severity: "media"
	});
	if (ctx.operations === 0) p.push({
		field: "operacoes",
		message: "Nenhuma operação interna lançada",
		severity: "media"
	});
	return p;
}
